package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.InventoryDtos.TransferRequest; import com.vynedam.stockai.model.StockTransfer; import com.vynedam.stockai.security.CurrentUser; import com.vynedam.stockai.service.TransferService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/transfers") public class TransferController {private final TransferService service;private final CurrentUser current;public TransferController(TransferService s,CurrentUser c){service=s;current=c;}@GetMapping List<StockTransfer>list(){return service.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','WAREHOUSE_EXECUTIVE')")ResponseEntity<StockTransfer>create(@Valid@RequestBody TransferRequest r,Authentication a){return ResponseEntity.status(201).body(service.create(r,current.id(a)));}@PostMapping("/{id}/approve")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PLANT_MANAGER','STORE_MANAGER')")StockTransfer approve(@PathVariable String id,Authentication a){return service.approve(id,current.id(a));}@PostMapping("/{id}/receive")@PreAuthorize("hasAnyRole('SUPER_ADMIN','STORE_MANAGER','WAREHOUSE_EXECUTIVE')")StockTransfer receive(@PathVariable String id,Authentication a){return service.receive(id,current.id(a));}}
